WITH flattened_attrs AS (SELECT id, coupon_codes, ship_to, SIZE(attributes) AS num_attributes, COALESCE(attributes['utm_source'], 'unknown') AS utm_source_or_default, EXISTS(coupon_codes, c -> c LIKE 'W%') AS has_welcome_code, ARRAY_JOIN(ARRAY_SORT(coupon_codes), ',') AS coupons_text FROM carts) SELECT CASE WHEN num_attributes >= 70 THEN 'PREMIUM' ELSE 'STANDARD' END AS num_attributes_tier, ROUND(AVG(num_attributes), 2) AS avg_num_attributes, MIN(num_attributes) AS min_num_attributes, COUNT(DISTINCT utm_source_or_default) AS distinct_utm_source_or_defaults FROM flattened_attrs GROUP BY ROLLUP (CASE WHEN num_attributes >= 70 THEN 'PREMIUM' ELSE 'STANDARD' END) HAVING min_num_attributes > 0;
